mapper.select:
SELECT 
FROM public.travel_map
WHERE city_id = #{cityId,typeHandler=com.guidepins.config.PostgresUuidTypeHandler}
  AND owner_id = #{ownerId,typeHandler=com.guidepins.config.PostgresUuidTypeHandler}
ORDER BY updated_at DESC, id

UPDATE public.travel_map m
SET visibility = #{visibility},
    updated_at = CASE WHEN m.visibility IS DISTINCT FROM #{visibility}
                      THEN clock_timestamp() ELSE m.updated_at END
WHERE m.id = #{id,typeHandler=com.guidepins.config.PostgresUuidTypeHandler}
  AND m.owner_id = #{ownerId,typeHandler=com.guidepins.config.PostgresUuidTypeHandler}
  AND EXISTS (SELECT 1 FROM public.user_account a
              WHERE a.id = m.owner_id AND a.status = 1)
RETURNING
